INSERT INTO `brands` VALUES (1,'Logitech','logitech','https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Logitech_logo.svg/512px-Logitech_logo.svg.png','Thụy Sĩ','Thương hiệu thiết bị ngoại vi máy tính & Gaming Gear hàng đầu thế giới với các công nghệ đột phá như Lightspeed và cảm biến HERO.',1,'2026-11-04 15:04:56'),(2,'Razer','razer','https://upload.wikimedia.org/wikipedia/en/thumb/4/40/Razer_snake_logo.svg/512px-Razer_snake_logo.svg.png','Mỹ / Singapore','Biểu tượng Rắn 3 đầu xanh lá huyền thoại - Dành riêng cho game thủ với dòng chuột DeathAdder, Viper và switch quang học thế hệ mới.',1,'2026-11-04 15:04:56'),(3,'Corsair','corsair','https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Corsair_Components_logo.svg/512px-Corsair_Components_logo.svg.png','Mỹ','Hệ sinh thái linh kiện và phụ kiện máy tính hiệu năng cao, nổi tiếng với bàn phím cơ K-series và tai nghe chất lượng studio.',1,'2026-11-04 15:04:56'),(4,'DareU','dareu','https://dareu.com.vn/wp-content/uploads/2021/04/logo-dareu.png','Trung Quốc','Thương hiệu Gaming Gear quốc dân tại thị trường Việt Nam - Tối ưu hiệu năng trên giá thành, độ bền vượt trội.',1,'2026-11-04 15:04:56'),(5,'SteelSeries','steelseries','https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/SteelSeries_logo.svg/512px-SteelSeries_logo.svg.png','Đan Mạch','Tiên phong trong ngành thể thao điện tử thế giới từ năm 2001, nổi danh với lót chuột QcK và dòng tai nghe Arctis Nova.',1,'2026-11-04 15:04:56'),(6,'HyperX','hyperx','https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/HyperX_Logo.svg/512px-HyperX_Logo.svg.png','Mỹ','Thương hiệu thuộc HP, thống trị các giải đấu Esports toàn cầu nhờ dòng tai nghe Cloud huyền thoại siêu êm ái.',1,'2026-11-06 13:03:04'),(7,'ASUS ROG','asus-rog','https://upload.wikimedia.org/wikipedia/en/thumb/a/a9/Asus_Republic_of_Gamers_logo.svg/512px-Asus_Republic_of_Gamers_logo.svg.png','Đài Loan','Republic of Gamers — Biểu tượng công nghệ phần cứng đỉnh cao, mang đến dòng gear Aim Lab và bàn phím Azoth custom cao cấp.',1,'2026-11-06 13:03:04'),(8,'Akko','akko','https://akkogear.com.vn/wp-content/uploads/2020/09/cropped-akko-icon.png','Đài Loan','Thương hiệu bàn phím cơ thiết kế thời thượng, phong cách độc đáo với keycap PBT Dye-sub và Akko Switch trứ danh.',1,'2026-11-06 13:03:04'),(9,'E-Dra','e-dra',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(10,'MCHOSE','mchose',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(11,'Lenovo','lenovo',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(12,'Ugreen','ugreen',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(13,'Apple','apple',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(14,'ASUS','asus',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(15,'Aula','aula',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(16,'Havit','havit',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(17,'HyperWork','hyperwork',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(18,'MSI','msi',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(19,'Rapoo','rapoo',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(20,'Dell','dell',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(21,'FL-Esports','fl-esports',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(22,'ESR','esr',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(23,'Satechi','satechi',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(24,'ZAGG','zagg',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(25,'Soundpeats','soundpeats',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(26,'Sony','sony',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(27,'Edifier','edifier',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(28,'JBL','jbl',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(29,'Samsung','samsung',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(30,'KZ','kz',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(31,'Baseus','baseus',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(32,'Robot','robot',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(33,'Xiaomi','xiaomi',NULL,NULL,NULL,1,'2026-11-11 14:22:12'),(34,'Sennheiser','sennheiser',NULL,NULL,NULL,1,'2026-11-11 14:22:12');
