--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` int(10) unsigned NOT NULL COMMENT 'FK → categories.id (cấp lá)',
  `brand_id` int(10) unsigned NOT NULL COMMENT 'FK → brands.id',
  `name` varchar(255) NOT NULL,
  `slug` varchar(300) NOT NULL,
  `sku` varchar(100) DEFAULT NULL COMMENT 'Mã sản phẩm tổng',
  `short_desc` text DEFAULT NULL,
  `full_desc` longtext DEFAULT NULL,
  `thumbnail_url` varchar(500) DEFAULT NULL,
  `base_price` decimal(12,0) NOT NULL DEFAULT 0 COMMENT 'Giá tham chiếu (VNĐ)',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `view_count` int(10) unsigned NOT NULL DEFAULT 0,
  `sold_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_prod_slug` (`slug`),
  KEY `idx_prod_category` (`category_id`),
  KEY `idx_prod_brand` (`brand_id`),
  KEY `idx_prod_featured` (`is_featured`),
  CONSTRAINT `fk_prod_brand` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`),
  CONSTRAINT `fk_prod_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng sản phẩm chính';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,7,1,'Logitech G Pro X Superlight 2','logitech-g-pro-x-superlight-2','LOG-GPXSL2','Chuột gaming không dây siêu nhẹ 60g, cảm biến HERO 2 25600 DPI',NULL,'/uploads/products/81ea560d06fe21de.jpg',1890000,1,1,296,0,'2026-11-04 15:04:56','2026-11-11 15:25:26'),(2,7,2,'Razer DeathAdder V3 HyperSpeed','razer-deathadder-v3-hyperspeed','RZR-DAV3HS','Chuột gaming không dây, thiết kế ergonomic, pin 300 giờ',NULL,'/uploads/products/12580bf621ced5c6.jpg',1590000,1,1,5,0,'2026-11-04 15:04:56','2026-11-11 15:25:08'),(3,7,4,'DareU EM901X Wireless','dareu-em901x-wireless','DRU-EM901X','Chuột gaming không dây 3 chế độ, cảm biến PAW3395, giá tốt',NULL,NULL,890000,0,1,5,0,'2026-11-04 15:04:56','2026-11-11 13:04:54'),(4,6,2,'Razer DeathAdder V3','razer-deathadder-v3','RZR-DAV3','Chuột gaming có dây siêu nhẹ 59g, Focus Pro 30K sensor',NULL,NULL,1290000,1,1,5,0,'2026-11-04 15:04:56','2026-11-11 13:04:55'),(5,6,3,'Corsair M75','corsair-m75','COR-M75','Chuột gaming có dây, cảm biến Marksman 26K, 10 nút lập trình',NULL,NULL,990000,0,1,5,0,'2026-11-04 15:04:56','2026-11-11 13:04:55'),(6,9,4,'DareU EK87 Pro','dareu-ek87-pro','DRU-EK87P','Bàn phím cơ TKL, switch DareU Sky V3, RGB, gasket mount',NULL,'/uploads/products/c40314293c70fad9.jpg',790000,0,1,21,0,'2026-11-04 15:04:56','2026-11-11 15:31:17'),(7,9,3,'Corsair K70 Pro Mini Wireless','corsair-k70-pro-mini-wireless','COR-K70PMW','Bàn phím cơ 65%, không dây, Cherry MX Switch, RGB',NULL,NULL,2890000,1,1,6,0,'2026-11-04 15:04:56','2026-11-11 13:04:55'),(8,12,2,'Razer BlackShark V2 X','razer-blackshark-v2-x','RZR-BSV2X','Tai nghe gaming có dây, driver 50mm, mic siêu định hướng',NULL,NULL,890000,0,1,5,0,'2026-11-04 15:04:56','2026-11-11 13:04:55'),(9,13,1,'Logitech G733 Lightspeed','logitech-g733-lightspeed','LOG-G733','Tai nghe gaming không dây LIGHTSPEED, pin 29 giờ, RGB',NULL,NULL,2290000,1,1,6,0,'2026-11-04 15:04:56','2026-11-11 13:47:42'),(10,4,5,'SteelSeries QcK Heavy XXL','steelseries-qck-heavy-xxl','SS-QCKHXXL','Lót chuột cỡ XXL 900x300mm, bề mặt vải mịn, đế cao su chống trượt',NULL,NULL,650000,0,1,5,0,'2026-11-04 15:04:56','2026-11-11 13:04:55'),(11,7,7,'ASUS ROG Harpe Ace Aim Lab Edition','asus-rog-harpe-ace-aim-lab-edition','ROG-HARPE-ACE','Chuột gaming siêu nhẹ 54g chuẩn thi đấu Esports phối hợp cùng Aim Lab.','Được phát triển cùng các tuyển thủ FPS chuyên nghiệp và phần mềm luyện phản xạ Aim Lab. Trang bị cảm biến quang học ROG AimPoint 36.000 DPI, công nghệ không dây ROG SpeedNova và trọng lượng chỉ 54g.','/uploads/products/f78d5c5711df21f8.jpg',2490000,1,1,1423,85,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(12,7,1,'Logitech G502 X PLUS Lightspeed','logitech-g502-x-plus-lightspeed','LOG-G502X-PLS','Chuột gaming huyền thoại tái sinh với switch lai quang-cơ LIGHTFORCE và LED RGB 8 vùng.','Biểu tượng chuột gaming bán chạy nhất hành tinh được nâng cấp toàn diện: Switch lai LIGHTFORCE, cảm biến HERO 25K, kết nối không dây Lightspeed độ trễ cực thấp và thời lượng pin lên đến 120 giờ.','/uploads/products/46496492342ef6fc.jpg',2890000,1,1,3103,140,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(13,7,2,'Razer Viper V3 Pro Wireless','razer-viper-v3-pro-wireless','RZR-VIPER-V3P','Chuột không dây siêu nhẹ 54g, Polling Rate thực 8000Hz với cảm biến Focus Pro 35K Gen-2.','Được kiểm chứng bởi hàng loạt ngôi sao Valorant thế giới. Thiết kế công thái học đối xứng chuẩn mực, trang bị Polling Rate 8000Hz không dây cho độ phản hồi tức thì.','/uploads/products/13f23dc03cff837d.jpg',3890000,1,1,2153,92,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(14,9,8,'Bàn Phím Cơ Akko 3098B Plus Multi-modes','ban-phim-co-akko-3098b-plus-multi-modes','AKKO-3098B-PLS','Bàn phím cơ 98 phím 3 chế độ kết nối, Keycap PBT Double-shot, Akko CS Switch.','Layout 98 phím nhỏ gọn nhưng vẫn giữ trọn vẹn cụm numpad tiện lợi. Kết nối linh hoạt Bluetooth 5.0, 2.4Ghz và cáp Type-C có thể tháo rời. Đèn nền RGB từng phím sống động.','/uploads/products/005f3517fd25f3d1.jpg',1690000,1,1,1893,115,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(15,11,1,'Logitech G PRO X TKL Lightspeed','logitech-g-pro-x-tkl-lightspeed','LOG-GPX-TKL','Bàn phím cơ thi đấu không dây Lightspeed chuẩn Esport với keycap PBT và điều khiển media.','Thiết kế Tenkeyless tối ưu không gian di chuột cho game thủ. Công nghệ không dây LIGHTSPEED đã được chứng minh tại các giải đấu vô địch thế giới.','/uploads/products/e13edc89ded286e8.jpg',3290000,1,1,1723,68,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(16,11,2,'Razer Huntsman V3 Pro Tenkeyless','razer-huntsman-v3-pro-tenkeyless','RZR-HUNTS-V3P','Bàn phím cơ quang học thế hệ 2 với Rapid Trigger và hành trình kích hoạt tùy biến 0.1mm - 4.0mm.','Tối ưu tuyệt đối cho tựa game CS2 và Valorant với tính năng Rapid Trigger siêu nhạy cho phép nhả phím và nhấn lại tức thì mà không cần chờ reset switch.','https://images.unsplash.com/photo-1541140532154-b024d705b909?w=600&auto=format&fit=crop&q=80',4590000,1,1,1253,42,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(17,9,7,'ASUS ROG Azoth Wireless Custom Keyboard','asus-rog-azoth-wireless-custom-keyboard','ROG-AZOTH-CST','Bàn phím cơ Custom 75% cao cấp có màn hình OLED, switch ROG NX lube sẵn và 3 lớp đệm tiêu âm.','Đỉnh cao bàn phím cơ kết hợp giữa cảm giác gõ mượt mà của custom keyboard và tính năng gaming không dây đẳng cấp. Màn hình OLED hiển thị thông số CPU, pin và hình ảnh GIF.','/uploads/products/6d36fcab033ed9fa.jpg',5490000,1,1,2803,54,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(18,13,6,'Tai Nghe HyperX Cloud III Wireless','tai-nghe-hyperx-cloud-iii-wireless','HPX-CLOUD3-WL','Tai nghe gaming không dây biểu tượng với pin 120 giờ, âm vòm DTS Headphone:X và đệm mút hoạt tính.','Kế thừa sự êm ái huyền thoại của Cloud II. Nâng cấp màng loa 53mm góc nghiêng, micro khử ồn 10mm siêu trong trẻo và pin đột phá lên đến 120 giờ chơi game liên tục.','/uploads/products/30edd9f0d7d1ff7c.jpg',2890000,1,1,3453,198,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(19,13,5,'SteelSeries Arctis Nova 7 Wireless','steelseries-arctis-nova-7-wireless','SS-NOVA7-WL','Tai nghe gaming đa nền tảng với hệ thống âm thanh Nova Acoustic và kết nối kép 2.4GHz + Bluetooth.','Hệ thống âm thanh Nova Acoustic tiên tiến với Driver High Fidelity. Kết nối đồng thời cả PC qua dongle 2.4G và điện thoại qua Bluetooth để vừa bắn game vừa đàm thoại.','/uploads/products/1c00751253f0364b.jpg',3690000,1,1,1683,77,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(20,13,3,'Corsair HS80 RGB Wireless Spatial Audio','corsair-hs80-rgb-wireless','COR-HS80-WL','Tai nghe gaming chuẩn âm thanh Dolby Atmos 24-bit/96kHz với micro đẳng cấp phòng thu broadcast.','Tái hiện không gian âm thanh 3D sống động với công nghệ Dolby Atmos độc quyền. Micro đa hướng broadcast-grade bắt trọn từng âm sắc giọng nói khi livestream.','/uploads/products/28d1d6f399111c70.jpg',2790000,1,1,1433,64,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(21,4,2,'Lót Chuột Razer Strider Chroma RGB','lot-chuot-razer-strider-chroma-rgb','RZR-STRIDER-RGB','Bàn di chuột lai Hybrid Cloth-Hard với 19 vùng chiếu sáng Razer Chroma RGB rực rỡ.','Bề mặt hybrid kết hợp giữa độ lướt nhanh mượt mà của pad cứng và khả năng kiểm soát hãm phanh chính xác của pad vải. Chống nước tràn và viền RGB liền mạch.','https://images.unsplash.com/photo-1541140532154-b024d705b909?w=600&auto=format&fit=crop&q=80',2290000,0,1,893,38,'2026-11-06 13:03:04','2026-11-11 13:04:55'),(22,4,1,'Hệ Thống Sạc Không Dây Logitech Powerplay','logitech-powerplay-wireless-charging','LOG-PWRPLAY','Bàn di chuột tích hợp công nghệ sạc không dây liên tục khi đang chơi game cho chuột Logitech G.','Giải pháp năng lượng tối thượng cho chuột không dây. Tạo ra trường điện từ trên toàn bộ bề mặt bàn di, liên tục nạp pin cho chuột ngay cả khi bạn đang thi đấu nảy lửa.','/uploads/products/46496492342ef6fc.jpg',2190000,1,1,1126,51,'2026-11-06 13:03:04','2026-11-11 15:38:22'),(23,6,1,'Chuột Gaming Logitech G502 Hero','chuot-choi-game-co-day-logitech-g502-hero','PKIT.242','Tương thích: Windows® 7 trở lên, macOS 10.11 trở lên, ChromeOS · Độ phân giải: 100 – 25.600 DPI · Kết nối: Dây USB','Tương thích: Windows® 7 trở lên, macOS 10.11 trở lên, ChromeOS\nĐộ phân giải: 100 – 25.600 DPI\nKết nối: Dây USB\nKhoảng cách kết nối (Độ dài dây): 2,1 m\nĐèn LED: LIGHTSYNC RGB','/uploads/products/8c36b8b0d0c3fad6.webp',920000,0,1,1358,519,'2026-10-27 14:22:12','2026-11-11 15:25:08'),(24,7,1,'Chuột Gaming không dây Logitech G304 Lightspeed','chuot-gaming-khong-day-logitech-g304-lightspeed','CH.LGT.01','Tương thích: Windows® 7 trở lênmacOS 10.13 trở lênChromeOS · Độ phân giải: 200 - 12000 DPI · Kết nối: LIGHTSPEED không dây','Tương thích: Windows® 7 trở lênmacOS 10.13 trở lênChromeOS\nĐộ phân giải: 200 - 12000 DPI\nKết nối: LIGHTSPEED không dây\nĐèn LED: Không\nThời gian dùng: 250 giờ','/uploads/products/09b4a226a16fdfdd.webp',725000,0,1,3577,110,'2026-08-21 14:22:12','2026-11-11 15:38:22'),(25,7,1,'Chuột không dây Logitech MX Master 4','chuot-khong-day-logitech-mx-master-4','chuot-khong-day-logitech-mx-master-4','Tương thích: Windows 10, 11 trở lênmacOS 13 trở lênLinuxChromeOS · Độ phân giải: 200-8000 DPI · Kết nối: BluetoothUSB ReceiverDây USB-C to A','Tương thích: Windows 10, 11 trở lênmacOS 13 trở lênLinuxChromeOS\nĐộ phân giải: 200-8000 DPI\nKết nối: BluetoothUSB ReceiverDây USB-C to A\nKhoảng cách kết nối (Độ dài dây): 10 m\nĐèn LED: Không\nThời gian dùng: Sử dụng được 70 ngày khi sạc đầy3 giờ sau khi sạc nhanh 1 phút','/uploads/products/2a7192e78d8bb4cf.webp',2890000,0,1,2329,435,'2026-08-24 14:22:12','2026-11-11 15:38:22'),(26,7,9,'Chuột gaming không dây E-Dra Thunderbird TM620W Triple Mode','chuot-gaming-khong-day-e-dra-thunderbird-tm620w-triple-mode','chuot-gaming-khong-day-e-dra-thunderbird-tm620w-triple-mode','Tương thích: WindowsMac · Độ phân giải: 12000 DPI · Kết nối: 2.4GhzBluetoothUSB Type C','Tương thích: WindowsMac\nĐộ phân giải: 12000 DPI\nKết nối: 2.4GhzBluetoothUSB Type C\nKhoảng cách kết nối (Độ dài dây): Kết nối khoảng cách: 10 métDây dài: 1.5 mét\nĐèn LED: LED RGB','/uploads/products/5c85d0d