--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reviews` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(10) unsigned NOT NULL COMMENT 'FK → products.id',
  `user_id` int(10) unsigned NOT NULL COMMENT 'FK → users.id',
  `order_id` int(10) unsigned DEFAULT NULL COMMENT 'FK → orders.id (đã mua mới được đánh giá)',
  `rating` tinyint(3) unsigned NOT NULL COMMENT '1-5 sao',
  `title` varchar(255) DEFAULT NULL,
  `content` text DEFAULT NULL,
  `is_approved` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rv_product` (`product_id`),
  KEY `idx_rv_user` (`user_id`),
  KEY `fk_rv_order` (`order_id`),
  CONSTRAINT `fk_rv_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rv_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rv_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `chk_rv_rating` CHECK (`rating` between 1 and 5)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Đánh giá & xếp hạng sản phẩm';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reviews`
--

LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (8,1,2,NULL,5,'Chuột nhẹ kinh khủng, bắn CS2 cực kỳ chuẩn!','Trước dùng chuột 80g đổi qua GPX 2 cảm giác như không cầm gì trên tay. Cảm biến nhạy, vẩy AWP mượt mà. Đóng gói của ZenTech rất cẩn thận, có bọc xốp chống sốc dày cộp.',1,'2026-11-04 16:30:00'),(9,1,3,NULL,5,'Màu trắng đẹp xuất sắc, pin trâu','Dùng 2 tuần rồi chưa cần sạc lại. Nút bấm quang học nảy tanh tách, không lo bị double-click như đời 1.',1,'2026-11-05 09:15:00'),(10,2,2,NULL,5,'Form cầm ôm tay hơn đời cũ','DeathAdder V3 HyperSpeed nhỏ gọn vừa tay người Việt mình hơn bản Pro. Feet chuột trơn mượt, ZenTech giao hàng trong vòng 2 tiếng nội thành quá ưng!',1,'2026-11-05 11:20:00'),(11,6,3,NULL,5,'Bàn phím quốc dân ngon nhất phân khúc 700K','Red switch gõ êm ru, có lót foam sẵn nên âm trầm ấm gõ văn phòng không sợ ồn đồng nghiệp. Giá quá tốt cho sinh viên.',1,'2026-11-05 14:00:00'),(12,14,2,NULL,5,'Akko không bao giờ làm thất vọng về độ đẹp','Phối màu Ocean Star cực kỳ cuốn mắt trên bàn làm việc. Switch mượt, stab cân sẵn không bị lọc xọc tẹo nào.',1,'2026-11-05 18:30:00'),(13,18,3,NULL,5,'Pin 120 giờ dùng mãi không thấy hết','Đeo êm tai cả ngày làm việc và leo rank đêm không bị cấn đau vành tai. Định vị bước chân PUBG rõ mồn một.',1,'2026-11-06 08:45:00'),(14,17,2,NULL,5,'Đỉnh chóp bàn phím custom','Màn hình OLED xem gif cưng xỉu, lube sẵn gõ mượt như bơ. Đắt xắt ra miếng, chế độ bảo hành 24 tháng ở ZenTech rất an tâm.',1,'2026-11-06 10:10:00');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

